def compute(vars):
    operating_lease = vars["v1"]
    total_payment = vars["v2"]

    if total_payment == 0:
        return None

    ratio = operating_lease / total_payment
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_lease": operating_lease,
            "total_payment": total_payment,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
